import React from 'react';
import { Routes, Route, Link } from 'react-router-dom';
import { TransactionProvider } from './context/TransactionContext';
import Dashboard from './pages/Dashboard/Dashboard';
import Transactions from './pages/Transactions/Transactions';
import TransactionDetails from './components/transactions/TransactionDetails/TransactionDetails';
import './App.css';

function App() {
  return (
    <TransactionProvider>
      <div className="app">
        {/* Temporary Navigation for Testing */}
        <nav style={{ padding: '20px', background: '#f0f0f0' }}>
          <ul style={{ display: 'flex', gap: '20px', listStyle: 'none', margin: 0 }}>
            <li><Link to="/">Dashboard</Link></li>
            <li><Link to="/transactions">Transactions</Link></li>
            <li><Link to="/transactions/TX123">Sample Transaction</Link></li>
          </ul>
        </nav>

        <main className="main-content">
          <Routes>
            <Route path="/" element={<Dashboard />} />
            <Route path="/transactions" element={<Transactions />} />
            <Route path="/transactions/:id" element={<TransactionDetails />} />
          </Routes>
        </main>

        {/* Optional: Add a footer */}
        <footer style={{ padding: '20px', textAlign: 'center', background: '#f0f0f0', marginTop: 'auto' }}>
          <p>Transaction Component Testing</p>
        </footer>
      </div>
    </TransactionProvider>
  );
}

export default App;
